-------------------------------------逻辑部分-----------------------------------------------
function CommonPackage_Use1KKPack(nItemId)
	-- 检测物品是否存在
	if not Item_ChkItem(nItemId) then
		return 
	end
	local nCommonPackage_UserId = Get_UserId()
	-- 设置掩码
	local nCommonPackage_Event = tCommonPackage_Stc["1KKPack"]["EventType"]
	local nCommonPackage_Data = tCommonPackage_Stc["1KKPack"]["DataType"]
	
	if not Task_StcInterval(nCommonPackage_Event,nCommonPackage_Data,1,4,nCommonPackage_UserId) then
		Sys_MsgBox(tCommonPackage_Text[3330203]["HaveGot"])
		return
	end
	local nCommonPackage_Dat = Get_UserStatisticValue(nCommonPackage_Event,nCommonPackage_Data,nCommonPackage_UserId)
	if nCommonPackage_Dat> tCommonPackage_Stc["1KKPack"]["Limit"] then 
		return
	end 
	if nCommonPackage_Dat < 1 then 
		--判断金币数量
		if not User_CanPutMoney2Bag(tCommonPackage_RewardItem[3330203][1]["RewardMoney"]["Value"]) then
			Sys_MsgBox(tJanuary_Props_Text[3307118]["FullMoney"])
			return
		end 
		Task_AddStatistic(nCommonPackage_Event,nCommonPackage_Data,1,1,nCommonPackage_UserId)
		Task_SetStcTimestamp(nCommonPackage_Event,nCommonPackage_Data,0,nCommonPackage_UserId)
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][1])

	else
		if not User_CanPutMoney2Bag(tCommonPackage_RewardItem[3330203][2]["RewardMoney"]["Value"]) then
			Sys_MsgBox(tJanuary_Props_Text[3307118]["FullMoney"])
			return
		end 
		if nCommonPackage_Dat == tCommonPackage_Stc["1KKPack"]["Limit"] then 
			if Item_ChkMulItem(nItemId,nItemId,1) and Item_DelItem(nItemId) then
				Task_AddStatistic(nCommonPackage_Event,nCommonPackage_Data,1,1,nCommonPackage_UserId)
				Task_SetStcTimestamp(nCommonPackage_Event,nCommonPackage_Data,0,nCommonPackage_UserId)
				RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][2])
				return
			end 
		end 
		
		Task_AddStatistic(nCommonPackage_Event,nCommonPackage_Data,1,1,nCommonPackage_UserId)
		Task_SetStcTimestamp(nCommonPackage_Event,nCommonPackage_Data,0,nCommonPackage_UserId)
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][2])
			
	end 

end 

function CommonPackage_ChoiseWeapon(nItemId,nChooseItemId)
	-- 检测物品是否存在
	if not Item_ChkItem(nItemId) then
		return 
	end
	local nCommonPackage_Space = RewardTemplate_GetRewardSpace(tCommonPackage_RewardItem[nItemId][nChooseItemId])
		-- 背包不足
	if not User_CheckLeftSpace(nCommonPackage_Space) then
		User_TalkChannel2005(tCommonPackage_Text["MaintainNoSpice"],nCommonPackage_UserId)
		return
	end
	
	RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][nChooseItemId])

	
end 

--使用物品
function CommonPackage_UseFurniture(nItemId)
	
	--活动过期
	if not Sys_ChkFullTime(tActivityTime["CommonPackageFurniture"]["ToolActivityTime"]) then
		if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then
		end
		local sLog = string.format(tCommonPackage_ToolForniture["LogId"],nItemId)
		Sys_SaveActionFestivalLog(sLog)
		User_TalkChannel2005(tCommonPackage_Text["DropItem"])
		return
	end

	--判断是否在房屋内使用
	local nHouseType = tCommonPackage_ToolForniture["House_Type"]
	local nPlayerId = Get_UserId()
	local nUserMapType = Get_MapType()
	local nMapLev = Get_MapResLev(nNowMapId)
	if not Sys_ParseNumbersContain(nHouseType,nUserMapType) then
		User_TalkChannel2005(tCommonPackage_Text["NoHome"])
		return
	end
	
	local nMapOwnerId = Get_MapOwnerId()
	if nMapOwnerId ~= nPlayerId then
		User_TalkChannel2005(tChristmas2015_MakeSnowman_Text["Furniture"]["TalkError1"])
		return
	end
	local nFurnitureLimit = 0
	if 2 <= nMapLev and nMapLev <= 6 then
		nFurnitureLimit = tCommonPackage_ToolForniture["FurnitureLimitTip"][nMapLev]
	else
		User_TalkChannel2005(tChristmas2015_MakeSnowman_Text["Furniture"]["Text"])
		return
	end
	--判断玩家房子内的家具数量
	if Get_NpcCount() >= nFurnitureLimit then
		local sErrorTip = string.format(tChristmas2015_MakeSnowman_Text["Furniture"]["TalkError2"],nMapLev,tCommonPackage_ToolForniture["FurnitureLimit"][nMapLev])
		User_TalkChannel2005(sErrorTip)
		return
	end

	Npc_RequestLayNpcByItem("CommonPackage_CreateNpc</N>" .. nItemId,2,tCommonPackage_ToolForniture["Lookface"][nItemId],0,nPlayerId)
end

--具体摆放家具
function CommonPackage_CreateNpc(nItemId)

	if Npc_CreatLayNpcByItem(tCommonPackage_Text["Name"][nItemId],2,32,tCommonPackage_ToolForniture["Lookface"][nItemId],0,0,0,0,0,tCommonPackage_ToolForniture["LookfaceFail"][nItemId]) then 
		if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then
			User_TalkChannel2005(string.format(tCommonPackage_Text["SnowmanNpc"],tCommonPackage_Text["Name"][nItemId]))
			return
		end
	end
	return
	
end

--删除过期物品
function CommonPackage_DelNpcItem(nItemId)
	if not Sys_ChkFullTime(tActivityTime["CommonPackageFurniture"]["ToolActivityTime"]) then
		Npc_DelDynaByID()
		User_TalkChannel2005(tCommonPackage_Text["DropItem"])
		return
	end
	
	Sys_DialogText(tCommonPackage_Text["Receive"]["Text"])
	Sys_DialogOption(tCommonPackage_Text["Receive"]["Option1"],"</F>CommonPackage_FoldFurniture</N>"..nItemId)
	Sys_DialogOption(tCommonPackage_Text["Receive"]["Option2"],"</F>NULL")
	Sys_DialogEnd()
end

--收起家具
function CommonPackage_FoldFurniture(nItemId)
	if not Sys_ChkFullTime(tActivityTime["CommonPackageFurniture"]["ToolActivityTime"]) then
		Npc_DelDynaByID()
		return
	end
	local nPlayerId = Get_UserId()
	local nMapOwnerId = Get_MapOwnerId()
	if nMapOwnerId ~= nPlayerId then
		return
	end
	if not User_CheckLeftSpace(1) then
		User_TalkChannel2005(tChristmas2015_MakeSnowman_Text["MsgBox"]["BagFull"])
		return
	end
	Npc_DelDynaByID()
	local tReward = CommonFunc_Copy(tCommonPackage_ToolForniture["Gift"])
	tReward["RewardItem"][1]["Id"] = nItemId
	RewardTemplate_UseItemAndMsg(tReward)
end

--万圣家具使用逻辑
function CommonPackage_HwlUseFurniture(nItemId)
	--活动过期
	if not Sys_ChkFullTime(tActivityTime["HalloweenPumpkin"]["ToolActivityTime"]) then
		if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then
		end
		local sLog = string.format(tCommonPackage_HlwToolForniture["LogId"],nItemId)
		Sys_SaveActionFestivalLog(sLog)
		User_TalkChannel2005(tCommonPackage_Text["DropItem"])
		return
	end
	--判断是否在房屋内使用
	local nHouseType = tCommonPackage_ToolForniture["House_Type"]
	local nPlayerId = Get_UserId()
	local nUserMapType = Get_MapType()
	local nMapLev = Get_MapResLev(nNowMapId)
	if not Sys_ParseNumbersContain(nHouseType,nUserMapType) then
		User_TalkChannel2005(tCommonPackage_Text["NoHome"])
		return
	end
	local nMapOwnerId = Get_MapOwnerId()
	if nMapOwnerId ~= nPlayerId then
		User_TalkChannel2005(tChristmas2015_MakeSnowman_Text["Furniture"]["TalkError1"])
		return
	end
	local nFurnitureLimit = 0
	if 2 <= nMapLev and nMapLev <= 6 then
		nFurnitureLimit = tCommonPackage_ToolForniture["FurnitureLimit"][nMapLev]
	else
		User_TalkChannel2005(tChristmas2015_MakeSnowman_Text["Furniture"]["Text"])
		return
	end
	--判断玩家房子内的家具数量
	if Get_NpcCount() >= nFurnitureLimit then
		local sErrorTip = string.format(tChristmas2015_MakeSnowman_Text["Furniture"]["TalkError2"],nMapLev,tCommonPackage_ToolForniture["FurnitureLimit"][nMapLev])
		User_TalkChannel2005(sErrorTip)
		return
	end
	Npc_RequestLayNpcByItem("CommonPackage_CreateNpc</N>" .. nItemId,2,tCommonPackage_ToolForniture["Lookface"][nItemId],0,nPlayerId)
end
--收起万圣家具
function CommonPackage_HwlFoldFurniture(nItemId)
	if not Sys_ChkFullTime(tActivityTime["HalloweenPumpkin"]["ToolActivityTime"]) then
		Npc_DelDynaByID()
		return
	end
	local nPlayerId = Get_UserId()
	local nMapOwnerId = Get_MapOwnerId()
	if nMapOwnerId ~= nPlayerId then
		return
	end
	if not User_CheckLeftSpace(1) then
		User_TalkChannel2005(tChristmas2015_MakeSnowman_Text["MsgBox"]["BagFull"])
		return
	end
	Npc_DelDynaByID()
	local tReward = CommonFunc_Copy(tCommonPackage_ToolForniture["Gift"])
	tReward["RewardItem"][1]["Id"] = nItemId
	RewardTemplate_UseItemAndMsg(tReward)
end
