function CommonPackage_PermanentStone(nItemId)
	if Item_ChkMulItem(nItemId,nItemId,20) then 
		local space = 1
		if User_CheckLeftSpace(space) then
			if Item_DelMulItem(nItemId,nItemId,20) then
				local nLogText = string.format("0,0,%d,20,12001200,2,0,0",nItemId)
				Sys_SaveActionFestivalLog(nLogText)
				RewardTemplate_UseItem(tCommonPackage_RewardItem[nItemId])
			end
		else
			Sys_MsgBox(tStoneFragments_Text["PermanentStoneFragment"]["NoSpace"])
		end
	else
		Sys_MsgBox(tStoneFragments_Text["PermanentStoneFragment"]["NotEnough"])
	end
end

function CommonPackage_UseItem(nItemId)
	if nItemId == 3320150 then
		if not Sys_ChkFullTime(tActivityTime["SaveBaohu"]["ActiveTime"]) then
			if Item_ChkMulItem(nItemId,nItemId,1) then
				Item_DelAllItemByType(nItemId)
				Sys_SaveActionFestivalLog(nCommonPackage_OverideItemIdGift[nItemId])
				User_TalkChannel2005(tSummerbigCharge[23010]["Nouse"])
				return
			end
		end
	end
	if tCommonPackage_RewardItem[nItemId] == nil then
		return
	end
	
	RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId])
end

-- 当天不提示2次确认
function CommonPackage_Close(nItemId)
	local nEvent = tCommonPackage_Stc["EventType"]
	local nType = tCommonPackage_Stc["DataType"]
	
	Task_SetStatistic(nEvent,nType,1,1)
	Task_SetStcTimestamp(nEvent,nType,0)
end

function CommonPackage_Check()
	local nEvent = tCommonPackage_Stc["EventType"]
	local nType = tCommonPackage_Stc["DataType"]
	
	if Task_StcInterval(nEvent,nType,1,4) then
		Task_SetStatistic(nEvent,nType,0,1)
		Task_SetStcTimestamp(nEvent,nType,0)
		return true
	end
	
	return Task_ChkStcValue(nEvent,nType,"==",0)
end

