-- 黑五狂欢币礼包
function CommonPackage_BlackFriPack(nItemId)
	-- 可使用时间前
	if Sys_ChkFullTime(tActivityTime["BlackFriPack"]["BeforeTime"]) then
		Sys_MsgBox(tBlackFriPack_Text["NotTime"])
		return false
	end
	
	-- 超过可使用时间
	if Sys_ChkFullTime(tActivityTime["BlackFriPack"]["AfterTime"]) then
		local nNum = Get_CountItemType(nItemId,0)
		
		if Item_ChkItem(nItemId) and Item_DelAllItemByType(nItemId) then
			User_TalkChannel2005(tBlackFriPack_Text["OutTime"][nItemId])
			
			-- 记录删除log
			local sLog = string.format(tCommonPackage_BlackFriPack_Log["Del"],nItemId,nNum)
			Sys_SaveActionFestivalLog(sLog)
		end
		
		return false
	end
	
	-- 可使用
	if Sys_ChkFullTime(tActivityTime["BlackFriPack"]["UseTime"]) then
		-- 判断背包空间
		local nSpace = RewardTemplate_GetRewardSpace(tCommonPackage_RewardItem[nItemId])
		if not User_CheckLeftSpace(nSpace) then
			Sys_MsgBox(tBlackFriPack_Text["FullBag"])
			return false
		end
		
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId])
		return true
	end
end

