-- 选择外套
function CommonPackage_CoatChoise(nCommonPackage_ItemId,nCommonPackage_Index)
	local nCommonPackage_UserId = Get_UserId()
	-- 检测玩家是否有该外套
	local sCommonPackage_Award = tCommonPackage_Text[nCommonPackage_ItemId]["AwardName"][nCommonPackage_Index]
	local nCommonPackage_CoatType = 1
	local nCommonPackage_CoatId = tCommonPackage_RewardItem[nCommonPackage_ItemId][nCommonPackage_Index]["RewardItem"][1]["Id"]
	if User_ChkStorageCoat(nCommonPackage_CoatType,nCommonPackage_CoatId,nCommonPackage_UserId) then
		User_TalkChannel2005(string.format(tCommonPackage_Text["MaintainOwn"],sCommonPackage_Award),nCommonPackage_UserId)
		return
	end
	-- 设置掩码
	local nCommonPackage_Event = tCommonPackage_MaintainStc["EventType"]
	local nCommonPackage_Data = tCommonPackage_MaintainStc["DataType"]
	
	Task_SetStatistic(nCommonPackage_Event, nCommonPackage_Data,nCommonPackage_Index,1,nCommonPackage_UserId)
	Task_SetStcTimestamp(nCommonPackage_Event,nCommonPackage_Data,0,nCommonPackage_UserId)
	
	local nCommonPackage_Dat = Get_UserStatisticValue(nCommonPackage_Event,nCommonPackage_Data,nCommonPackage_UserId)
	-- 设置对话内容
	tItem[nCommonPackage_ItemId]["Text121"] = string.format(tCommonPackage_Text[nCommonPackage_ItemId]["Text121"],sCommonPackage_Award)
	
	-- 跳转对话
	LinkItemGossipFunc_New(nCommonPackage_ItemId,tCommonPackage_MaintainData["DiaIndex"] )
end

