function CommonPackage_MaintainGiveAward(nCommonPackage_ItemId)
	-- 奖励引索
	local nCommonPackage_Event = tCommonPackage_MaintainStc["EventType"]
	local nCommonPackage_Data = tCommonPackage_MaintainStc["DataType"]
	local nCommonPackage_UserId = Get_UserId()
	
	local nCommonPackage_Dat = Get_UserStatisticValue(nCommonPackage_Event,nCommonPackage_Data,nCommonPackage_UserId)
	
	local nCommonPackage_Space = RewardTemplate_GetRewardSpace(tCommonPackage_RewardItem[nCommonPackage_ItemId][nCommonPackage_Dat])
		-- 背包不足
	if not User_CheckLeftSpace(nCommonPackage_Space) then
		User_TalkChannel2005(tCommonPackage_Text["MaintainNoSpice"],nCommonPackage_UserId)
		return
	end
	
	-- 重置掩码值
	Task_SetStatistic(nCommonPackage_Event, nCommonPackage_Data,0,1,nCommonPackage_UserId)
	Task_SetStcTimestamp(nCommonPackage_Event, nCommonPackage_Data,0,nCommonPackage_UserId)
	
	-- 给奖励
	RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nCommonPackage_ItemId][nCommonPackage_Dat])
end

function CommonPackage_OpenSevenLoginPack(nItemId,nChoose)
	-- 检测物品是否存在
	if not Item_ChkMulItem(nItemId,nItemId,1) then
		return
	end
	
	-- 判断背包空间
	local nSpace = RewardTemplate_GetRewardSpace(tCommonPackage_SevenLoginPack[nItemId][nChoose])
	if not User_CheckLeftSpace(nSpace) then
		Sys_MsgBox(string.format(tCommonPackage_Text["Msg"]["NoMoreSpace"],nSpace))
		return
	end
	
	RewardTemplate_UseItemAndMsg(tCommonPackage_SevenLoginPack[nItemId][nChoose])
end

