function CommonPackage_SetGlobal()
	local nGlobalId = tCommonPackage_BattlePass[3312242][1]["GlobalId"]
	local sDataStr5 = Get_SysDynaGlobalDataStr5(nGlobalId)
	if sDataStr5 == "1" then
		return
	end
	Sys_SetSynaGlobalData(nGlobalId,0,0)
	Sys_SetSynaGlobalData(nGlobalId,1,0)
	Sys_SetSynaGlobalData(nGlobalId,2,0)
	Sys_SetSynaGlobalDataStr5(nGlobalId,"1")
end

function CommonPackage_ClearGlobal()
	local nGlobalId = tCommonPackage_BattlePass[3312242][1]["GlobalId"]
	Sys_SetSynaGlobalDataStr5(nGlobalId,"0")
end

--维护补偿礼包
function CommonPackage_NaintenanceBag()
	local nGlobalId = tCommonPackage_Cont["Maintain"]["GlobalId"]
	local nData = Get_SysDynaGlobalData0(nGlobalId)
	
	--判断是否发放补偿礼包
	if nData <= 0 then
		return
	end
	
	local nUserId = Get_UserId()
	local nEvent = tCommonPackage_Login[1]["EventType"]
	local nType = tCommonPackage_Login[1]["DataType"]
	
	--已经发过
	if Get_UserStatisticValue(nEvent,nType,nUserId) > 0 then
		return
	end
	
	--等级判断
	local nLevel = tCommonPackage_Cont["Maintain"]["Level"]
	local nMetempsychosis = tCommonPackage_Cont["Maintain"]["Metempsychosis"]
	
	if not User_JudgeLevelAndMetempsychosis(nLevel,nMetempsychosis,nUserId) then
		Task_SetStatistic(nEvent,nType,1,1,nUserId)
		return
	end
	
	local nIndex = 1
	
	--判断发放哪种礼包
	if nData ~= 1 then
		nIndex = 2
	end
	
	RewardTemplate_UseItemAndMsg(tCommonPackage_Login[nIndex],nUserId)
end

-- 服务器问题补偿-礼包放送（10.24）
function CommonPackage_CompensatePack()
	--发放时间
	if not Sys_ChkFullTime(tActivityTime["CompensatePack"]["ActiveTime"]) then
		return
	end
	
	local nUserId = Get_UserId()
	local nEvent = tCommonPackage_Stc["CompensatePack"]["EventType"]
	local nType = tCommonPackage_Stc["CompensatePack"]["DataType"]
	
	--已经发过
	if Get_UserStatisticValue(nEvent,nType,nUserId) > 0 then
		return
	end
	
	Task_SetStatistic(nEvent,nType,1,1,nUserId)
	
	--给礼包，这边是要做成强插方式给奖励，不涉及其他条件判断，所以使用这个接口
	RewardTemplate_Reward(tCommonPackage_RewardItem["CompensatePack"],nUserId)
end
--上线触发
function CommonPackage_Login()
	CommonPackage_NaintenanceBag()
	CommonPackage_CompensatePack()
	
	--发放时间
	if not Sys_ChkFullTime(tActivityTime["CommonPackage"]["Login"]) then
		return
	end
	
	local nUserId = Get_UserId()
	local nEvent = tCommonPackage_Stc["LoginBag"]["EventType"]
	local nType = tCommonPackage_Stc["LoginBag"]["DataType"]
	
	--已经发过
	if Get_UserStatisticValue(nEvent,nType,nUserId) > 0 then
		return
	end
	
	Task_SetStatistic(nEvent,nType,1,1,nUserId)
	
	--给礼包，这边是要做成强插方式给奖励，不涉及其他条件判断，所以使用这个接口
	RewardTemplate_Reward(tCommonPackage_RewardItem["Login"],nUserId)
	
	local nActionId = tCommonPackage_Cont["Login"]["Mail"]["ActionId"]
	local nExistDay = tCommonPackage_Cont["Login"]["Mail"]["ExistDay"]
	local sSender = tCommonPackage_Text["Mail"]["Sender"]
	local sTitle = tCommonPackage_Text["Mail"]["Title"]
	local sContent = tCommonPackage_Text["Mail"]["Content"]
	
	--发邮件
	Sys_SendMail(nUserId,0,0,nActionId,0,nExistDay,sSender,sTitle,sContent)
end
