function CommonPackage_OpenItemTwo(nItemId)
	if not Item_ChkItem(nItemId) then
		return
	end
	-- 背包空间判断
	if not RewardTemplate_CheckSpace(tCommonPackage_RewardItem[nItemId][2]) then
		Sys_MsgBox(tCommonPackage_Text[nItemId]["NoSpace"])
		return
	end
	-- 成功
	if Sys_Random(tCommonPackage_RewardItem[nItemId][2]["Radom"],10000) then
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][2])
