	Sys_MsgBox(tCommonPackage_Text[nItemId]["Fail"])
end

--服务器启动
function CommonPackage_Start()
	local nGlobalId = tCommonPackage_Cont["Maintain"]["GlobalId"]
	
	--判断是否开放
	if Get_SysDynaGlobalData0(nGlobalId) <= 0 then
		return
	end
	
	local nData = Get_SysDynaGlobalData1(nGlobalId)
	
	if nData == 0 then
		Sys_SetSynaGlobalData1(nGlobalId,os.time())
	else
		local nTimeSub = os.time() - nData
		
		--判断是否超过两天
		if nTimeSub >= tCommonPackage_Cont["Maintain"]["Time"] then
			Sys_SetSynaGlobalData0(nGlobalId, 0)
			Sys_SetSynaGlobalData1(nGlobalId, 0)
		end
	end
end

