--返回玩家身上的物品价值
--物品id	判断是赠点还是天石，1天石，2赠点
--对白购买，价格自己手动配置
function CommonPackage_ChatReturnPrice(nItemId,nType,nNum)
	local nTip = tCommonPackage_ChatZhengKou[nItemId]
	
	if nTip == nil then
		return nil,nil,nil,nil
	end
	
	local nZheItemId = 0
	local nReturnPrice = 0
	
	local nOriginalPrice = tCommonPackage_ChatZhengKou[nItemId]["OriginMoney"]*nNum

	
	for i,v in pairs(tCommonPackage_NewCutprice["ItemId"][nType]) do
		
		if Item_ChkMulItem(v[1],v[1],1) and (nOriginalPrice >= v[2]) then
			nZheItemId = v[1]
			nReturnPrice = v[3]
			break
		end
	end
	
	if nZheItemId == 0 and nReturnPrice == 0 then
		return nil,nil,nil,nil
	end
	
	local sTring = tCommonPackage_ChatZhengKou[nItemId]["MyEmoneyLog"]
	
	return nReturnPrice,0,sTring,nZheItemId
end

