function CommonPackage_DeleteTicket(nZhengItemId,nItemId)
	
	if Item_ChkMulItem(nZhengItemId,nZhengItemId,1) and Item_DelMulItem(nZhengItemId,nZhengItemId,1) then
		local sLog = string.format(tCommonPackage_NewCutprice["StcLog"],nZhengItemId,nItemId)
		Sys_SaveActionFestivalLog(sLog)
