function CommonPackage_CopyTableReward(nItemId,sIndex,nChoose)
	local tCommonPackage_Copy = CommonFunc_Copy(tCommonPackage_RewardItem[nItemId])
	if sIndex == "TitleType" then 
		tCommonPackage_Copy["RewardTitle"]["TitleType"] = nChoose
		tCommonPackage_Copy["RewardTitle"]["TitleId"] = nChoose
	elseif sIndex == "RewardItem" then
		tCommonPackage_Copy["RewardItem"][1]["Id"] = nChoose
	else
		return
	end
	RewardTemplate_UseItemAndMsg(tCommonPackage_Copy)
end
function CommonPackage_TreasureBowl(nItemId)
	if not Item_ChkItem(nItemId) then 
		return
	end
	local nCommonPackage_UserId = Get_UserId()
	local nCommonPackage_Stc = Get_UserStatisticValue(tCommonPackage_Stc["TreasureBowl"]["EventType"],tCommonPackage_Stc["TreasureBowl"]["DataType"],nCommonPackage_UserId)
	if nCommonPackage_Stc < tCommonPackage_Stc["TreasureBowl"]["Limit"] then 
		if RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][1]) then
			Task_AddStatistic(tCommonPackage_Stc["TreasureBowl"]["EventType"],tCommonPackage_Stc["TreasureBowl"]["DataType"],1,1,nCommonPackage_UserId)
			Task_SetStcTimestamp(tCommonPackage_Stc["TreasureBowl"]["EventType"],tCommonPackage_Stc["TreasureBowl"]["DataType"],0)
			Sys_SaveEmoneyBuy(tCommonPackage_EmoneyLog[3329739])
		end
	elseif nCommonPackage_Stc == tCommonPackage_Stc["TreasureBowl"]["Limit"] then 
		if RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][2]) then
			Task_AddStatistic(tCommonPackage_Stc["TreasureBowl"]["EventType"],tCommonPackage_Stc["TreasureBowl"]["DataType"],1,1,nCommonPackage_UserId)
			Task_SetStcTimestamp(tCommonPackage_Stc["TreasureBowl"]["EventType"],tCommonPackage_Stc["TreasureBowl"]["DataType"],0)
			Sys_SaveEmoneyBuy(tCommonPackage_EmoneyLog[3329739])
		end
	else
		local nCommonPackage_Num = Get_CountItemType(nItemId, 0)
		Item_DelMulItem(nItemId, nItemId, nCommonPackage_Num)
	end
end


--忍者觉醒预约宝箱
function CommonPackage_OpenRenZhePack(nItemId,nIndex)
	--物品判断
	if not Item_ChkMulItem(nItemId,nItemId,1) then
		return 
	end 
	local nUserId = Get_UserId()
	
	if nIndex==1 then 
		--条件判断
		local bJudge = TermsOfUse_Main(nItemId,tCommonPackage_RewardItem[nItemId][nIndex])
	
		if not bJudge then
			return
		end
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][nIndex],nUserId,bJudge)
	end 
	
	if nIndex==2 then 
		--天石判断
		local nUserEmoney = Get_UserEMoney(nUserId)
		if nUserEmoney < 199 then
			User_TalkChannel2005(tCommonPackage_Text[nItemId]["LackEmoney"])
			return
		end
		
		--其他条件判断
		local bJudge = TermsOfUse_Main(nItemId,tCommonPackage_RewardItem[nItemId][nIndex])
	
		if not bJudge then
			return
		end
		
		--扣除天石给奖励
		if User_AddEMoney(-199) then
			--记录log
			Sys_SaveEmoneyBuy(tCommonPackage_EmoneyLog[3329804])
			RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][nIndex],nUserId,bJudge)
		end
	end 
	
end 
