tItem[3311040] = tItem[3311040] or {}
tItem[3311040]["Function"] = function(nItemId,sItemName)
	-- 判断无赠服务器
	if not SpecialServer_ChkNoGiftServer() then
		return false
	end	
	
	local nNum = tCommonPackage_RewardItem[nItemId]["RewardMoney"]["Value"]
	-- 判断银两上限
	if not User_CanPutMoney2Bag(nNum) then
		User_TalkChannel2005(tDoubleEleven2017_DAMC_Text["Limit"]["Money"])
		return false
	end
	
	RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId])
end

