-----battle pass 
for i= 3312180,3312185 do
	tItem[i] = tItem[i] or {}
	tItem[i]["Function"] = function(nItemId,sItemName)
		if not Item_ChkItem(nItemId) then
			return
		end
		local nUserId = Get_UserId()
		if not Item_DelItem(nItemId) then
			return
		end
		if RewardTemplate_NewRandom(tCommonPackage_RewardItem,nItemId) then
			local flat,tNum = Probabil_RandomAward(tCommonPackage_BattlePass,nItemId)  
			-- if Sys_ChkFullTime(tCommonPackage_Data["AtTime"]) then
				local nScore = tNum[1]["tAward"][1]["Score"]
				User_AddUserSeasonScore(nScore,nUserId)
				local sLog = string.format(tCommonPackage_Data["ItemLog"],nItemId,nScore)
				Sys_SaveActionFestivalLog(sLog)
			end
		-- end
	end
end


