-- 玄鼋经验丹
tItem[3312767] = tItem[3312767] or {}
tItem[3312767]["Function"] = function(nItemId,sItemName)
	--判断物品是否存在
	if not Item_ChkItem(nItemId) then
		return
	end
	local nUserId = Get_UserId()
	local nUserLevel = Get_UserLevel(nUserId)
	if nUserLevel >= 50 and nUserLevel <= 90 then
		if Item_ChkItem(nItemId) and Item_DelItem(nItemId) then
			User_AddLevel(1)
			local sLog = string.format("0,0,3312767,1,12001367,2,%d,%d",nUserLevel-1,nUserLevel)
			Sys_SaveActionFestivalLog(sLog)
			User_EffectAdd(tCommonPackage_RewardItem[nItemId][1]["RewardEffect"]["SzObj"],tCommonPackage_RewardItem[nItemId][1]["RewardEffect"]["Effect"])
		end
	elseif nUserLevel >= 91 then
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][2])
	else
		Sys_MsgBox(tCommonPackage_Text[3312767]["NoLev"])
	end
end
