-- 7天时效鹿坐骑
tItem[3314384] = tItem[3314384] or {}
tItem[3314384]["Function"] = function (nItemId,sItemName)
	if not Item_ChkItem(nItemId) then
		return
	end
	local nEvent = tCommonPackage_BattlePass["BpStc"][1]["EventType"]
	local nType = tCommonPackage_BattlePass["BpStc"][1]["DataType"]
	-- local nData = Get_UserStatisticValue(nEvent,nType)
	--打掩码
	Task_AddStatistic(nEvent,nType,1,1)
	Task_SetStcTimestamp(nEvent,nType,0)
	local nDataNum = Get_UserStatisticValue(nEvent,nType)

	if nDataNum ~= 0 and (nDataNum%55 == 0)  then
		RewardTemplate_UseItemAndMsg(tCommonPackage_BattlePass[3314384][2])
		local nItem = tCommonPackage_BattlePass[3314384][2]["RewardItem"][1]["Id"]
		local sAddItemName = Get_ItemtypeName(nItem)
		local sStr = string.format(tCommonPackage_Text[3314384]["Get"],sAddItemName,nDataNum)
		Sys_MsgBox(sStr)
	else
		local tReward = RewardTemplate_RandomReward(tCommonPackage_BattlePass[3314384],1)
		local nItem = tReward[1]["tAward"][1]["RewardItem"][1]["Id"]
		local sAddItemName = Get_ItemtypeName(nItem)
		local sStr = string.format(tCommonPackage_Text[3314384]["Get"],sAddItemName,nDataNum)
		Sys_MsgBox(sStr)
	end
end

-- 高级豪侠令碎片
