		Sys_MsgBox(tCommonPackage_Text[3314385]["No"])
		return
	end
	RewardTemplate_UseItemAndMsg(tCommonPackage_BattlePass[3314385])
end
tItem[3314385]["Time"] = tActivityTime["BattlePass"]["ActivityTime"]

-- 138000分
tItem[3314386] = tItem[3314386] or {}
tItem[3314386]["Function"] = function(nItemId,sItemName)
	if not Item_ChkItem(nItemId) then
		return
	end
	if Item_DelItem(nItemId) then
		local nUserId = Get_UserId()
		local nScore = tCommonPackage_BattlePass["BpScore"][3314386]
		User_AddUserSeasonScore(nScore,nUserId)
		local sLog = string.format(tCommonPackage_Data["ItemLog"],nItemId,nScore)
		Sys_SaveActionFestivalLog(sLog)
	end
end

