tItem[3330399]["Function"] = function(nItemId)
	if CommonFunc_GetAfterActivityTime(tActivityTime["AprilMoneyMerge"]["ActTime"]) then
		--转化为气力值
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId]["TimeOut"])
		return
	end
	if  Get_CountItemType(nItemId,0) < 5 then
		--
		Sys_MsgBox(tCommonPackage_Text[3330399]["MsgBox"]["Fragment"])
		return
	end
	RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId])
end

