tItem[3315618] = tItem[3315618] or {}
tItem[3315618]["Function"] = function(nItemId,sItemName)
	-- 判断背包
	if not Item_ChkItem(nItemId) then
		return
	end
	
	local nCommonPackage_UserId = Get_UserId()
	local nCommonPackage_Pro = Get_NewUserProfession(nCommonPackage_UserId)
	
	-- 判断是不是忍者职业
	if not (nCommonPackage_Pro >= G_PRO_Ninja0_New and nCommonPackage_Pro <= G_PRO_Ninja49_New) then
		-- 非忍者职业
		local nCommonPackage_EmoneyMono = Get_UserMonoEMoney(nCommonPackage_UserId)
		local nCommonPackage_RewardEmoneyMono = tCommonPackage_RewardItem[nItemId][1]["RewardEMoneyMono"]["Value"]
		
		if nCommonPackage_EmoneyMono + nCommonPackage_RewardEmoneyMono > G_User_MaxEmoneyMono then
			User_TalkChannel2005(tMayPKMonth_Text["Item"]["Text141"])
			Sys_MsgBox(tMayPKMonth_Text["Item"]["Text141"])
			return
		end
		
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][1])
	else
		-- 忍者职业
		local nCommonPackage_EmoneyMono = Get_UserMonoEMoney(nCommonPackage_UserId)
		local nCommonPackage_RewardEmoneyMono = tCommonPackage_RewardItem[nItemId][2]["RewardEMoneyMono"]["Value"]
		
		if nCommonPackage_EmoneyMono + nCommonPackage_RewardEmoneyMono > G_User_MaxEmoneyMono then
			User_TalkChannel2005(tMayPKMonth_Text["Item"]["Text141"])
			Sys_MsgBox(tMayPKMonth_Text["Item"]["Text141"])
			return
		end
		
		RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][2])
	end
end
