--3330792-3330794秘术精华神纹可选礼盒使用逻辑
function CommonPackage_JuneOptionalGift(nItemId,nTip)
	if not Item_ChkItem(nItemId) then
		return
	end
	if not RewardTemplate_CheckSpace(tCommonPackage_RewardItem[nItemId][nTip]) then
		return
	end
	RewardTemplate_UseItemAndMsg(tCommonPackage_RewardItem[nItemId][nTip])
end

